#include "media/d64.h"
#include "media/t64.h"
#include "media/tap.h"
#include "media/prg.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"line %d: %s\n",__LINE__,#x);return 1;}}while(0)
#define ROUND(kind,obj) do{rc_state_writer w;rc_sw_init(&w);rc_sw_header(&w,"test",#kind,NULL,0);rc_sw_begin(&w,"FILE",0);rc_##kind##_save(&(obj),&w);rc_sw_end(&w);CHECK(rc_sw_finish(&w));rc_##kind##_close(&(obj));rc_state_reader r;CHECK(rc_sr_open(&r,w.data,w.size,error,sizeof error)&&rc_sr_chunk(&r,"FILE",0));CHECK(rc_##kind##_load(&(obj),&r));rc_sw_free(&w);}while(0)
static int disk(void){char error[128];rc_d64 d;CHECK(rc_d64_create(&d,NULL,NULL,error,sizeof error));uint8_t data[256]={0};data[1]=4;data[2]=1;data[3]=8;data[4]=0x42;CHECK(rc_d64_write_sector(&d,1,0,data));memset(data,0,256);data[1]=255;data[2]=0x82;data[3]=1;memset(data+5,0xa0,16);memcpy(data+5,"TEST",4);data[30]=1;CHECK(rc_d64_write_sector(&d,18,1,data));memcpy(data,rc_d64_sector(&d,18,0),256);--data[4];data[5]&=0xfeu;CHECK(rc_d64_write_sector(&d,18,0,data));
    rc_d64_entry e;size_t count=0;CHECK(rc_d64_directory(&d,&e,1,&count,error,sizeof error)&&count==1&&e.blocks==1);uint8_t *program=NULL;size_t size=0;CHECK(rc_d64_extract(&d,&e,&program,&size,error,sizeof error)&&size==3&&program[2]==0x42);free(program);ROUND(d64,d);CHECK(rc_d64_sector(&d,1,0)[4]==0x42&&d.image->dirty);rc_d64_close(&d);return 0;}
static int tape_container(void){char error[128];const uint8_t bytes[]={1,2,3};rc_t64_program programs[2]={{0x801,bytes,3,{0}},{0xc000,bytes,3,{0}}};memcpy(programs[0].name,"FIRST",5);memcpy(programs[1].name,"SECOND",6);rc_t64 t;CHECK(rc_t64_create(&t,programs,2,NULL,error,sizeof error));rc_t64_entry e;CHECK(rc_t64_entry_at(&t,1,&e)&&e.address==0xc000&&e.length==3);rc_image_put16(t.image->data+64+4,0xc3c6);CHECK(rc_t64_entry_at(&t,0,&e)&&e.length==3);ROUND(t64,t);CHECK(t.count==2&&rc_t64_entry_at(&t,0,&e)&&!memcmp(t.image->data+e.offset,bytes,3));rc_t64_close(&t);return 0;}
static int pulse_tape(void){char error[128];rc_tap t;CHECK(rc_tap_create(&t,0,error,sizeof error));CHECK(rc_tap_append(&t,384,error,sizeof error)&&rc_tap_append(&t,2048,error,sizeof error)&&rc_tap_append(&t,4097,error,sizeof error));CHECK(t.version==1);uint32_t pulse=0;CHECK(rc_tap_next(&t,&pulse)&&pulse==384);ROUND(tap,t);CHECK(rc_tap_next(&t,&pulse)&&pulse==2048);CHECK(rc_tap_next(&t,&pulse)&&pulse==4097&&!rc_tap_next(&t,&pulse));rc_tap_close(&t);return 0;}
static int program(void){char error[128];const uint8_t bytes[]={0xa9,0x42,0x60};rc_prg p;CHECK(rc_prg_create(&p,0x801,bytes,3,NULL,1,error,sizeof error));CHECK(p.image->size==31&&!memcmp(p.image->data,"C64File\0",8));ROUND(prg,p);CHECK(p.address==0x801&&p.length==3&&!memcmp(rc_prg_data(&p),bytes,3));rc_prg_close(&p);CHECK(rc_prg_create(&p,0x801,bytes,3,NULL,0,error,sizeof error)&&p.image->size==5);rc_prg_close(&p);return 0;}
int main(int argc,char **argv){if(argc!=2)return 2;int status=!strcmp(argv[1],"d64")?disk():!strcmp(argv[1],"t64")?tape_container():!strcmp(argv[1],"tap")?pulse_tape():!strcmp(argv[1],"prg")?program():2;if(!status)printf("%s container and state OK\n",argv[1]);return status;}
